def f(gin):
    H,W=len(gin),len(gin[0])
    # components by color (4-conn)
    seen=set(); objs=[]
    for r in range(H):
        for c in range(W):
            if gin[r][c]!=0 and (r,c) not in seen:
                col=gin[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=a+dr,b+dc
                        if 0<=rr<H and 0<=cc<W and gin[rr][cc]==col and (rr,cc) not in seen:
                            seen.add((rr,cc)); st.append((rr,cc))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                objs.append({'col':col,'r0':min(rs),'c0':min(cs),'h':max(rs)-min(rs)+1,'w':max(cs)-min(cs)+1,
                             'n':len(cells),'cells':set(cells)})
    # order by original column then row
    objs.sort(key=lambda o:(o['c0'],o['r0']))
    out=[[0]*W for _ in range(H)]
    def render(shape):
        for (r,c),v in shape.items(): out[r][c]=v
    fig={}  # cell->color
    for i,o in enumerate(objs):
        hr,wc=o['h'],o['w']
        if i==0: tr,tc=0,0
        else:
            prev=objs[i-1]
            br=(prev['r0']+prev['h']-1, prev['c0']+prev['w']-1)
            tr,tc=br[0],br[1]
        # push down while overlap with rendered figure (excluding own cells)
        own={(tr+r_,tc+c_) for r_ in range(hr) for c_ in range(wc)}
        push=0
        while True:
            cells={(tr+rr,tc+cc) for rr in range(hr) for cc in range(wc)}
            ov=cells & set(fig) - own
            if not ov: break
            push+=1
            if push>20: raise Exception('push loop')
            tr+=1
        # place
        for rr in range(hr):
            for cc in range(wc):
                fig[(tr+rr,tc+cc)]=o['col']
        # trim BR corner iff some successor's final TL == that cell
        trim_br=False
        for j in range(i+1,len(objs)):
            nxt=objs[j]
            nr,nc=nxt['r0']+nxt['h']-1, nxt['c0']+nxt['w']-1
            if (nr,nc)==(tr+hr-1, tc+wc-1) and fig.get((tr+hr-1,tc+wc-1))==o['col']:
                trim_br=True
        if trim_br: del fig[(tr+hr-1,tc+wc-1)]
    return out

